11: // MigrateV1Events moves the v1 events directory to the archive directory if it exists.
12: // If eventsDir does not exist, it is a no-op and returns nil.
13: func MigrateV1Events(eventsDir, archiveDir string) error {
14: 	info, err := os.Stat(eventsDir)
15: 	if errors.Is(err, os.ErrNotExist) {
16: 		return nil
17: 	}
18: 	if err != nil {
19: 		return fmt.Errorf("stat events dir: %w", err)
20: 	}
21: 	if !info.IsDir() {
22: 		return fmt.Errorf("events path %s is not a directory", eventsDir)
23: 	}
24: 
25: 	cleanEvents := filepath.Clean(eventsDir)
26: 	cleanArchive := filepath.Clean(archiveDir)
27: 	if cleanEvents == cleanArchive {
28: 		return nil
29: 	}
30: 
31: 	if err := os.MkdirAll(filepath.Dir(cleanArchive), 0o755); err != nil {
32: 		return fmt.Errorf("create archive parent dir: %w", err)
33: 	}
34: 
35: 	// Try direct atomic rename first
36: 	if err := os.Rename(cleanEvents, cleanArchive); err == nil {
37: 		return nil
38: 	}
39: 
40: 	// If destination already exists or rename fails across devices, move contents recursively
41: 	if err := moveDirContents(cleanEvents, cleanArchive); err != nil {
42: 		return fmt.Errorf("migrate events from %s to %s: %w", cleanEvents, cleanArchive, err)
43: 	}
44: 
45: 	return os.RemoveAll(cleanEvents)
46: }
