48: func moveDirContents(srcDir, dstDir string) error {
49: 	if err := os.MkdirAll(dstDir, 0o755); err != nil {
50: 		return err
51: 	}
52: 	entries, err := os.ReadDir(srcDir)
53: 	if err != nil {
54: 		return err
55: 	}
56: 	for _, entry := range entries {
57: 		srcPath := filepath.Join(srcDir, entry.Name())
58: 		dstPath := filepath.Join(dstDir, entry.Name())
59: 		if entry.IsDir() {
60: 			if err := moveDirContents(srcPath, dstPath); err != nil {
61: 				return err
62: 			}
63: 		} else {
64: 			if err := os.Rename(srcPath, dstPath); err != nil {
65: 				if err := copyFile(srcPath, dstPath); err != nil {
66: 					return err
67: 				}
68: 				if err := os.Remove(srcPath); err != nil {
69: 					return err
70: 				}
71: 			}
72: 		}
73: 	}
74: 	return nil
75: }
