package index

import (
	"context"
	"database/sql"
	"fmt"
	"strings"
)

// UpsertEntryAnchors replaces all anchors for the specified entry.
func (idx *Index) UpsertEntryAnchors(ctx context.Context, entryID string, anchors []string) error {
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors WHERE entry_id = ?", entryID); err != nil {
			return fmt.Errorf("deleting existing anchors: %w", err)
		}
		if len(anchors) == 0 {
			return nil
		}
		stmt, err := tx.PrepareContext(ctx, "INSERT INTO entry_anchors (entry_id, anchor) VALUES (?, ?)")
		if err != nil {
			return fmt.Errorf("preparing anchor insert: %w", err)
		}
		defer stmt.Close()

		for _, a := range anchors {
			trimmed := strings.TrimSpace(a)
			if trimmed == "" {
				continue
			}
			if _, err := stmt.ExecContext(ctx, entryID, trimmed); err != nil {
				return fmt.Errorf("inserting anchor %q: %w", trimmed, err)
			}
		}
		return nil
	})
}

// LookupByAnchor returns entry IDs matching the anchor prefix using LIKE.
func (idx *Index) LookupByAnchor(ctx context.Context, anchor string) ([]string, error) {
	pattern := anchor
	if !strings.HasSuffix(pattern, "%") {
		pattern += "%"
	}

	query := `
	SELECT DISTINCT entry_id 
	FROM entry_anchors 
	WHERE anchor LIKE ? 
	ORDER BY entry_id
	`
	rows, err := idx.db.QueryContext(ctx, query, pattern)
	if err != nil {
		return nil, fmt.Errorf("looking up by anchor: %w", err)
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, fmt.Errorf("scanning anchor entry_id: %w", err)
		}
		results = append(results, id)
	}
	if results == nil {
		results = []string{}
	}
	return results, rows.Err()
}

// LookupByAnchorExact returns entry IDs exactly matching the anchor.
func (idx *Index) LookupByAnchorExact(ctx context.Context, anchor string) ([]string, error) {
	query := `
	SELECT DISTINCT entry_id 
	FROM entry_anchors 
	WHERE anchor = ? 
	ORDER BY entry_id
	`
	rows, err := idx.db.QueryContext(ctx, query, anchor)
	if err != nil {
		return nil, fmt.Errorf("looking up exact anchor: %w", err)
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, fmt.Errorf("scanning exact anchor entry_id: %w", err)
		}
		results = append(results, id)
	}
	if results == nil {
		results = []string{}
	}
	return results, rows.Err()
}

func (idx *Index) getEntryAnchors(ctx context.Context, entryID string) ([]string, error) {
	query := `SELECT anchor FROM entry_anchors WHERE entry_id = ? ORDER BY rowid ASC`
	rows, err := idx.db.QueryContext(ctx, query, entryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var anchors []string
	for rows.Next() {
		var a string
		if err := rows.Scan(&a); err != nil {
			return nil, err
		}
		anchors = append(anchors, a)
	}
	return anchors, rows.Err()
}

package index

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
)

// UpsertEntry inserts or updates an entry in the entries table.
func (idx *Index) UpsertEntry(ctx context.Context, entry dossiers.Entry) error {
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		var createdAtStr, updatedAtStr string
		if !entry.CreatedAt.IsZero() {
			createdAtStr = entry.CreatedAt.Format(time.RFC3339Nano)
		}
		if !entry.UpdatedAt.IsZero() {
			updatedAtStr = entry.UpdatedAt.Format(time.RFC3339Nano)
		}

		query := `
		INSERT INTO entries (id, type, dossier_scope, text, source, verified, closes_when, created_at, updated_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(id) DO UPDATE SET
			type = excluded.type,
			dossier_scope = excluded.dossier_scope,
			text = excluded.text,
			source = excluded.source,
			verified = excluded.verified,
			closes_when = excluded.closes_when,
			created_at = excluded.created_at,
			updated_at = excluded.updated_at
		`
		_, err := tx.ExecContext(ctx, query,
			entry.ID,
			string(entry.Type),
			entry.DossierScope,
			entry.Text,
			entry.Source,
			entry.Verified,
			entry.ClosesWhen,
			createdAtStr,
			updatedAtStr,
		)
		if err != nil {
			return fmt.Errorf("upserting entry %s: %w", entry.ID, err)
		}

		if len(entry.Anchors) > 0 {
			if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors WHERE entry_id = ?", entry.ID); err != nil {
				return err
			}
			stmt, err := tx.PrepareContext(ctx, "INSERT INTO entry_anchors (entry_id, anchor) VALUES (?, ?)")
			if err != nil {
				return err
			}
			defer stmt.Close()
			for _, a := range entry.Anchors {
				trimmed := strings.TrimSpace(a)
				if trimmed == "" {
					continue
				}
				if _, err := stmt.ExecContext(ctx, entry.ID, trimmed); err != nil {
					return err
				}
			}
		}
		return nil
	})
}

// GetEntry retrieves a single entry by ID, returning ErrNotFound if missing.
func (idx *Index) GetEntry(ctx context.Context, id string) (*dossiers.Entry, error) {
	query := `
	SELECT id, type, dossier_scope, text, COALESCE(source, ''), COALESCE(verified, ''), COALESCE(closes_when, ''), COALESCE(created_at, ''), COALESCE(updated_at, '')
	FROM entries
	WHERE id = ?
	`
	var e dossiers.Entry
	var entryType, source, verified, closesWhen, createdAtStr, updatedAtStr string
	err := idx.db.QueryRowContext(ctx, query, id).Scan(
		&e.ID,
		&entryType,
		&e.DossierScope,
		&e.Text,
		&source,
		&verified,
		&closesWhen,
		&createdAtStr,
		&updatedAtStr,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("getting entry: %w", err)
	}
	e.Type = dossiers.EntryType(entryType)
	e.Source = source
	e.Verified = verified
	e.ClosesWhen = closesWhen
	if createdAtStr != "" {
		if t, err := time.Parse(time.RFC3339Nano, createdAtStr); err == nil {
			e.CreatedAt = t
		} else if t, err := time.Parse(time.RFC3339, createdAtStr); err == nil {
			e.CreatedAt = t
		}
	}
	if updatedAtStr != "" {
		if t, err := time.Parse(time.RFC3339Nano, updatedAtStr); err == nil {
			e.UpdatedAt = t
		} else if t, err := time.Parse(time.RFC3339, updatedAtStr); err == nil {
			e.UpdatedAt = t
		}
	}

	anchors, err := idx.getEntryAnchors(ctx, id)
	if err != nil {
		return nil, fmt.Errorf("getting entry anchors: %w", err)
	}
	e.Anchors = anchors

	return &e, nil
}

// DeleteEntry removes an entry and its associated anchors and error patterns.
func (idx *Index) DeleteEntry(ctx context.Context, id string) error {
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors WHERE entry_id = ?", id); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM error_patterns WHERE entry_id = ?", id); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM entries WHERE id = ?", id); err != nil {
