// ListEntriesByScope lists all entries matching the given dossier scope.
func (idx *Index) ListEntriesByScope(ctx context.Context, scope string) ([]dossiers.Entry, error) {
	query := `
	SELECT id, type, dossier_scope, text, COALESCE(source, ''), COALESCE(verified, ''), COALESCE(closes_when, ''), COALESCE(created_at, ''), COALESCE(updated_at, '')
	FROM entries
	WHERE dossier_scope = ?
	ORDER BY id
	`
	rows, err := idx.db.QueryContext(ctx, query, scope)
	if err != nil {
		return nil, fmt.Errorf("listing entries by scope: %w", err)
	}
	defer rows.Close()

	var results []dossiers.Entry
	for rows.Next() {
		var e dossiers.Entry
		var entryType, source, verified, closesWhen, createdAtStr, updatedAtStr string
		if err := rows.Scan(
			&e.ID,
			&entryType,
			&e.DossierScope,
			&e.Text,
			&source,
			&verified,
			&closesWhen,
			&createdAtStr,
			&updatedAtStr,
		); err != nil {
			return nil, fmt.Errorf("scanning entry: %w", err)
		}
		e.Type = dossiers.EntryType(entryType)
		e.Source = source
		e.Verified = verified
		e.ClosesWhen = closesWhen
		if createdAtStr != "" {
			if t, err := time.Parse(time.RFC3339Nano, createdAtStr); err == nil {
				e.CreatedAt = t
			} else if t, err := time.Parse(time.RFC3339, createdAtStr); err == nil {
				e.CreatedAt = t
			}
		}
		if updatedAtStr != "" {
			if t, err := time.Parse(time.RFC3339Nano, updatedAtStr); err == nil {
				e.UpdatedAt = t
			} else if t, err := time.Parse(time.RFC3339, updatedAtStr); err == nil {
				e.UpdatedAt = t
			}
