// InsertErrorPattern registers an error pattern for a failure-signature entry.
func (idx *Index) InsertErrorPattern(ctx context.Context, entryID, commandPrefix, pattern, scope string) error {
	query := `
	INSERT INTO error_patterns (entry_id, command_prefix, pattern, dossier_scope)
	VALUES (?, ?, ?, ?)
	`
	_, err := idx.db.ExecContext(ctx, query, entryID, commandPrefix, pattern, scope)
	if err != nil {
		return fmt.Errorf("inserting error pattern: %w", err)
	}
	return nil
}

// LookupErrorPatterns returns matching failure-signature entries for a command or prefix.
func (idx *Index) LookupErrorPatterns(ctx context.Context, commandPrefix string) ([]ErrorPatternResult, error) {
	prefix := strings.TrimSpace(commandPrefix)
	query := `
	SELECT entry_id, COALESCE(command_prefix, ''), pattern, dossier_scope
	FROM error_patterns
	WHERE command_prefix = ?
	   OR command_prefix = ''
	   OR (? != '' AND command_prefix != '' AND ? LIKE (command_prefix || '%'))
	   OR (? != '' AND command_prefix != '' AND command_prefix LIKE (? || '%'))
	ORDER BY entry_id
	`
	rows, err := idx.db.QueryContext(ctx, query, prefix, prefix, prefix, prefix, prefix)
	if err != nil {
		return nil, fmt.Errorf("looking up error patterns: %w", err)
	}
	defer rows.Close()

	var results []ErrorPatternResult
	for rows.Next() {
		var r ErrorPatternResult
		if err := rows.Scan(&r.EntryID, &r.CommandPrefix, &r.Pattern, &r.DossierScope); err != nil {
			return nil, fmt.Errorf("scanning error pattern result: %w", err)
		}
		results = append(results, r)
	}
	if results == nil {
		results = []ErrorPatternResult{}
	}
	return results, rows.Err()
}

// UpsertAlias records or updates a dossier scope alias.
func (idx *Index) UpsertAlias(ctx context.Context, oldScope, newScope string) error {
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, "DELETE FROM aliases WHERE old_scope = ?", oldScope); err != nil {
			return err
		}
		nowStr := time.Now().UTC().Format(time.RFC3339Nano)
		_, err := tx.ExecContext(ctx, "INSERT INTO aliases (old_scope, new_scope, created_at) VALUES (?, ?, ?)", oldScope, newScope, nowStr)
		return err
	})
}

// ResolveAlias follows alias chains to resolve an old scope name to its current scope.
func (idx *Index) ResolveAlias(ctx context.Context, scope string) (string, error) {
	curr := strings.TrimSpace(scope)
	if curr == "" {
		return "", nil
	}
	visited := make(map[string]bool)
	maxDepth := 10
	for i := 0; i < maxDepth; i++ {
		var next string
		err := idx.db.QueryRowContext(ctx, "SELECT new_scope FROM aliases WHERE old_scope = ? ORDER BY rowid DESC LIMIT 1", curr).Scan(&next)
		if errors.Is(err, sql.ErrNoRows) {
			break
		}
		if err != nil {
			return "", fmt.Errorf("resolving alias for %s: %w", curr, err)
		}
		next = strings.TrimSpace(next)
		if next == "" || next == curr || visited[next] {
			break
		}
		visited[curr] = true
		curr = next
	}
	return curr, nil
}

// InsertHistory records a retired or superseded entry in entry_history.
func (idx *Index) InsertHistory(ctx context.Context, entry dossiers.Entry, reason string) error {
	id := entry.ID
	if id == "" {
		id = fmt.Sprintf("hist-%d", time.Now().UnixNano())
	}
	entryID := entry.ID
	if entryID == "" {
		entryID = id
	}
	retiredReason := reason
	if retiredReason == "" {
		retiredReason = entry.RetiredReason
	}
	retiredAt := ""
	if !entry.UpdatedAt.IsZero() {
		retiredAt = entry.UpdatedAt.Format(time.RFC3339Nano)
	} else {
		retiredAt = time.Now().UTC().Format(time.RFC3339Nano)
	}

	query := `
	INSERT INTO entry_history (id, entry_id, type, dossier_scope, text, reason, superseded_by, retired_at)
	VALUES (?, ?, ?, ?, ?, ?, ?, ?)
	`
	_, err := idx.db.ExecContext(ctx, query,
		id,
		entryID,
		string(entry.Type),
		entry.DossierScope,
		entry.Text,
		retiredReason,
		entry.SupersededBy,
		retiredAt,
	)
	if err != nil {
		return fmt.Errorf("inserting entry history: %w", err)
	}
	return nil
}

// GetHistory returns history entries for a given entry ID.
func (idx *Index) GetHistory(ctx context.Context, entryID string) ([]dossiers.Entry, error) {
	query := `
	SELECT id, entry_id, type, dossier_scope, COALESCE(text, ''), COALESCE(reason, ''), COALESCE(superseded_by, ''), COALESCE(retired_at, '')
	FROM entry_history
	WHERE entry_id = ? OR id = ?
	ORDER BY rowid ASC
	`
	rows, err := idx.db.QueryContext(ctx, query, entryID, entryID)
	if err != nil {
		return nil, fmt.Errorf("getting entry history: %w", err)
	}
	defer rows.Close()

	var results []dossiers.Entry
	for rows.Next() {
		var histID, eID, eType, scope, text, reason, supersededBy, retiredAtStr string
		if err := rows.Scan(&histID, &eID, &eType, &scope, &text, &reason, &supersededBy, &retiredAtStr); err != nil {
			return nil, err
		}
		var updatedAt time.Time
		if retiredAtStr != "" {
			if t, err := time.Parse(time.RFC3339Nano, retiredAtStr); err == nil {
				updatedAt = t
			} else if t, err := time.Parse(time.RFC3339, retiredAtStr); err == nil {
				updatedAt = t
			}
		}
		results = append(results, dossiers.Entry{
			ID:            eID,
			Type:          dossiers.EntryType(eType),
			DossierScope:  scope,
			Text:          text,
			Retired:       true,
			RetiredReason: reason,
			SupersededBy:  supersededBy,
			UpdatedAt:     updatedAt,
		})
	}
	if results == nil {
		results = []dossiers.Entry{}
	}
	return results, rows.Err()
}

