// RebuildFromOpLog rebuilds all v2 tables in the index from the op log.
func (idx *Index) RebuildFromOpLog(ctx context.Context, opsReader *ops.Reader) error {
	// Clear all v2 tables (entries, entry_anchors, error_patterns, aliases, entry_history, entries_fts)
	err := idx.WriteTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors"); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM error_patterns"); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM aliases"); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM entry_history"); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM entries"); err != nil {
			return err
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("clearing v2 tables: %w", err)
	}

	if opsReader == nil {
		return nil
	}

	// Read ops to collect error pattern metadata for failure signatures
	type errPatternMeta struct {
		commandPrefix string
		pattern       string
	}
	errPatMap := make(map[string]errPatternMeta)
	for batch, err := range opsReader.Iterate(ctx) {
		if err != nil {
			return fmt.Errorf("reading ops for error patterns: %w", err)
		}
		if batch == nil {
			continue
		}
		for _, op := range batch.Ops {
			var cmdPrefix, pattern string
			if p, ok := op.Fields["pattern"].(string); ok {
				pattern = p
			} else if p, ok := op.Fields["error_pattern"].(string); ok {
				pattern = p
			}
			if cp, ok := op.Fields["command_prefix"].(string); ok {
				cmdPrefix = cp
			} else if cp, ok := op.Fields["command"].(string); ok {
				cmdPrefix = cp
			}
			if pattern != "" || cmdPrefix != "" {
				errPatMap[op.EntryID] = errPatternMeta{
					commandPrefix: cmdPrefix,
					pattern:       pattern,
				}
			}
		}
	}

	// Project dossiers from op log
	projector := dossiers.NewProjector(opsReader)
	dossiersMap, err := projector.Project(ctx)
	if err != nil {
		return fmt.Errorf("projecting dossiers from op log: %w", err)
	}

	// Upsert entries, anchors, error patterns, and history
	for _, d := range dossiersMap {
		for _, entry := range d.Entries {
			if err := idx.UpsertEntry(ctx, entry); err != nil {
				return fmt.Errorf("upserting entry %s: %w", entry.ID, err)
			}
			if err := idx.UpsertEntryAnchors(ctx, entry.ID, entry.Anchors); err != nil {
				return fmt.Errorf("upserting anchors for %s: %w", entry.ID, err)
			}
			if entry.Type == dossiers.EntryTypeFailureSignature {
				cmdPrefix := ""
				pattern := entry.Text
				if info, ok := errPatMap[entry.ID]; ok {
					if info.commandPrefix != "" {
						cmdPrefix = info.commandPrefix
					}
					if info.pattern != "" {
						pattern = info.pattern
					}
				}
				if err := idx.InsertErrorPattern(ctx, entry.ID, cmdPrefix, pattern, entry.DossierScope); err != nil {
					return fmt.Errorf("inserting error pattern for %s: %w", entry.ID, err)
				}
			}
		}
		for _, hEntry := range d.History {
			reason := hEntry.RetiredReason
			if reason == "" {
				if hEntry.SupersededBy != "" {
					reason = "superseded"
				} else {
					reason = "retired"
				}
			}
			if err := idx.InsertHistory(ctx, hEntry, reason); err != nil {
