+	// Clear all v2 tables (entries, entry_anchors, error_patterns, aliases, entry_history, entries_fts)
+	err := idx.WriteTx(ctx, func(tx *sql.Tx) error {
+		if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors"); err != nil {
