+		if err != nil {
+			return fmt.Errorf("reading ops for error patterns: %w", err)
+		}
+		if batch == nil {
+			continue
+		}
+		for _, op := range batch.Ops {
+			var cmdPrefix, pattern string
+			if p, ok := op.Fields["pattern"].(string); ok {
