+				cmdPrefix = cp
+			} else if cp, ok := op.Fields["command"].(string); ok {
+				cmdPrefix = cp
+			}
+			if pattern != "" || cmdPrefix != "" {
+				errPatMap[op.EntryID] = errPatternMeta{
+					commandPrefix: cmdPrefix,
+					pattern:       pattern,
