func TestEntryCRUD(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "crud_test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	// 1. Get non-existent entry returns ErrNotFound
	_, err = idx.GetEntry(ctx, "non-existent")
	if !errors.Is(err, index.ErrNotFound) {
		t.Fatalf("expected ErrNotFound, got %v", err)
	}

	// 2. UpsertEntry + GetEntry round-trip
	now := time.Now().UTC().Truncate(time.Millisecond)
	entry := dossiers.Entry{
		ID:           "inv-001",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/index",
		Text:         "Index must always be synchronized with op log",
		Anchors:      []string{"internal/core/index/index.go"},
		Source:       "manual",
		Verified:     "2026-10-11",
		ClosesWhen:   "never",
		CreatedAt:    now,
		UpdatedAt:    now,
	}

	if err := idx.UpsertEntry(ctx, entry); err != nil {
		t.Fatalf("UpsertEntry: %v", err)
	}

	got, err := idx.GetEntry(ctx, "inv-001")
	if err != nil {
		t.Fatalf("GetEntry: %v", err)
	}
	if got.ID != entry.ID || got.Type != entry.Type || got.DossierScope != entry.DossierScope || got.Text != entry.Text {
		t.Fatalf("GetEntry mismatch: got %+v, want %+v", got, entry)
	}
	if len(got.Anchors) != 1 || got.Anchors[0] != "internal/core/index/index.go" {
		t.Fatalf("GetEntry anchors mismatch: got %v", got.Anchors)
	}
	if got.Verified != entry.Verified || got.ClosesWhen != entry.ClosesWhen {
		t.Fatalf("GetEntry metadata mismatch: got %+v", got)
	}

	// 3. ListEntriesByScope
	entries, err := idx.ListEntriesByScope(ctx, "core/index")
	if err != nil {
		t.Fatalf("ListEntriesByScope: %v", err)
	}
	if len(entries) != 1 || entries[0].ID != "inv-001" {
		t.Fatalf("ListEntriesByScope unexpected result: %v", entries)
	}

	entriesOther, err := idx.ListEntriesByScope(ctx, "other/scope")
	if err != nil {
		t.Fatalf("ListEntriesByScope other: %v", err)
	}
	if len(entriesOther) != 0 {
		t.Fatalf("ListEntriesByScope expected 0, got %d", len(entriesOther))
	}

	// 4. DeleteEntry
	if err := idx.DeleteEntry(ctx, "inv-001"); err != nil {
		t.Fatalf("DeleteEntry: %v", err)
	}
	_, err = idx.GetEntry(ctx, "inv-001")
	if !errors.Is(err, index.ErrNotFound) {
		t.Fatalf("expected ErrNotFound after delete, got %v", err)
	}
}

func TestSearchEntries_FTS5(t *testing.T) {
