func TestEntryAnchors(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "anchors_test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	entryID := "inv-anchor-test"
	anchors := []string{
		"internal/core/index/index.go",
		"internal/core/index/entries.go",
		"internal/core/index/entry_anchors.go",
	}

	if err := idx.UpsertEntryAnchors(ctx, entryID, anchors); err != nil {
		t.Fatalf("UpsertEntryAnchors: %v", err)
	}

	// Prefix lookup with LookupByAnchor
	ids, err := idx.LookupByAnchor(ctx, "internal/core/index")
	if err != nil {
		t.Fatalf("LookupByAnchor: %v", err)
	}
	if len(ids) != 1 || ids[0] != entryID {
		t.Fatalf("expected [%s], got %v", entryID, ids)
	}

	// Exact lookup with LookupByAnchorExact
	exactIDs, err := idx.LookupByAnchorExact(ctx, "internal/core/index/entries.go")
	if err != nil {
		t.Fatalf("LookupByAnchorExact: %v", err)
	}
	if len(exactIDs) != 1 || exactIDs[0] != entryID {
		t.Fatalf("expected [%s], got %v", entryID, exactIDs)
	}

	// Exact lookup non-matching prefix
	exactNonMatch, err := idx.LookupByAnchorExact(ctx, "internal/core/index")
	if err != nil {
		t.Fatalf("LookupByAnchorExact non-match: %v", err)
	}
	if len(exactNonMatch) != 0 {
		t.Fatalf("expected 0 exact matches, got %d", len(exactNonMatch))
	}

	// Replace anchors
	newAnchors := []string{"cmd/repo-memory/main.go"}
	if err := idx.UpsertEntryAnchors(ctx, entryID, newAnchors); err != nil {
		t.Fatalf("UpsertEntryAnchors replace: %v", err)
	}

	oldLookup, err := idx.LookupByAnchor(ctx, "internal/core/index")
	if err != nil {
		t.Fatalf("LookupByAnchor old: %v", err)
	}
	if len(oldLookup) != 0 {
		t.Fatalf("expected old anchors to be replaced, got %v", oldLookup)
	}

	newLookup, err := idx.LookupByAnchorExact(ctx, "cmd/repo-memory/main.go")
	if err != nil {
		t.Fatalf("LookupByAnchorExact new: %v", err)
	}
	if len(newLookup) != 1 || newLookup[0] != entryID {
		t.Fatalf("expected [%s], got %v", entryID, newLookup)
	}
}

func TestErrorPatterns(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "error_patterns_test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
