func TestAliases(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "aliases_test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	if err := idx.UpsertAlias(ctx, "scope-a", "scope-b"); err != nil {
		t.Fatalf("UpsertAlias a->b: %v", err)
	}
	if err := idx.UpsertAlias(ctx, "scope-b", "scope-c"); err != nil {
		t.Fatalf("UpsertAlias b->c: %v", err)
	}
	if err := idx.UpsertAlias(ctx, "scope-c", "scope-final"); err != nil {
		t.Fatalf("UpsertAlias c->final: %v", err)
	}

	// Follow chain
	resolved, err := idx.ResolveAlias(ctx, "scope-a")
	if err != nil {
		t.Fatalf("ResolveAlias scope-a: %v", err)
	}
	if resolved != "scope-final" {
		t.Fatalf("expected scope-final, got %s", resolved)
	}

	// Middle of chain
	resolvedMid, err := idx.ResolveAlias(ctx, "scope-b")
	if err != nil {
		t.Fatalf("ResolveAlias scope-b: %v", err)
	}
	if resolvedMid != "scope-final" {
		t.Fatalf("expected scope-final, got %s", resolvedMid)
	}

	// Unaliased scope returns itself
	resolvedUnknown, err := idx.ResolveAlias(ctx, "unknown-scope")
	if err != nil {
		t.Fatalf("ResolveAlias unknown: %v", err)
	}
	if resolvedUnknown != "unknown-scope" {
		t.Fatalf("expected unknown-scope, got %s", resolvedUnknown)
	}

	// Cycle protection
	if err := idx.UpsertAlias(ctx, "cycle-1", "cycle-2"); err != nil {
		t.Fatalf("UpsertAlias cycle-1: %v", err)
	}
	if err := idx.UpsertAlias(ctx, "cycle-2", "cycle-1"); err != nil {
		t.Fatalf("UpsertAlias cycle-2: %v", err)
	}
	cycleRes, err := idx.ResolveAlias(ctx, "cycle-1")
	if err != nil {
		t.Fatalf("ResolveAlias cycle: %v", err)
	}
	if cycleRes != "cycle-1" && cycleRes != "cycle-2" {
		t.Fatalf("expected cycle to break gracefully, got %s", cycleRes)
	}
}

